with lines as (select id, elem.product_id, elem.qty, elem.price from (select id, explode(items) as elem from carts) e) select *, cume_dist() over (order by price asc) as price_cume_dist, dense_rank() over (order by qty desc nulls last) as qty_dense_rank, dense_rank() over (order by price desc) as price_dense_rank, percent_rank() over (order by product_id desc) as product_id_percent_rank, percent_rank() over (order by qty desc nulls last) as qty_percent_rank from lines
